#include "tensor/sycl/SYCLTensorBackend.hpp"
#endif

namespace
{

using XT = nn::XTensorBackend;
using CL = nn::OpenCLTensorBackend;
using DV = nn::DeviceTensorBackend;

// Per-backend tolerance: GPU fp32 kernels round differently from the host
// serial loops, so chained/reduced ops need a looser bound than the default
// used for the exact host-math backends (XTensor, and Device — which is
// itself just an XTensor host mirror, see DeviceTensorBackend.hpp).
template <typename Backend>
constexpr float parity_tol()
{
    return 1e-4F;
}
template <>
constexpr float parity_tol<CL>()
{
    return 3e-4F;
}
#ifdef NN_BACKEND_SYCL
using SY = nn::SYCLTensorBackend;
template <>
constexpr float parity_tol<SY>()
{
    return 3e-4F;
}
#endif

// Skip gracefully for backends whose device isn't actually present at test
// run time. XTensor and Device never need this (Device is host math only).
// OpenCLTensorBackend.cpp/SYCLTensorBackend.cpp are the only backends that
// throw rather than silently running on host if no device is available (see
// cmake/OpenCLGpuCapabilityCheck.cmake / SyclGpuCapabilityCheck.cmake for the
// configure-time side of that "no fallback" policy) — skip here instead of
// letting every TYPED_TEST fail identically when a device is genuinely
// absent (e.g. CI runners without a GPU).
template <typename Backend>
void skip_if_backend_unavailable()
{
}
template <>
void skip_if_backend_unavailable<CL>()
{
    if (!nn::opencl::OpenCLContext::instance().is_available())
        GTEST_SKIP() << "No OpenCL device available — parity suite skipped for OpenCLTensorBackend";
}
#ifdef NN_BACKEND_SYCL
template <>
void skip_if_backend_unavailable<SY>()
{
    if (!SY::sycl_runtime_available())
        GTEST_SKIP() << "No SYCL device available — parity suite skipped for SYCLTensorBackend";
}
#endif

const cnpy::npz_t& refs()
{
    static const cnpy::npz_t data = []
    {
        const std::filesystem::path p =
            std::filesystem::path(__FILE__).parent_path() / "fixtures" / "pytorch_refs.npz";
        return cnpy::npz_load(p.string());
    }();
    return data;
}

const cnpy::NpyArray& arr(const std::string& key)
{
    const auto it = refs().find(key);
    EXPECT_NE(it, refs().end()) << "missing fixture key: " << key;
    return it->second;
}

// IMPORTANT: use only the structured accessors at(i,j)/at(i,j,k)/at(i,j,k,l),
// never the linear at(k). The linear accessor exposes backend storage order
// (row-major for xtensor, column-major for the OpenCL backend), so filling a
// tensor from row-major fixture data via at(k) would transpose it on OpenCL.
// at(i,j)… address the same *logical* element on every backend. Fixture arrays
// are numpy C-order, so a C-order multi-index walk matches them.
using Shape = std::vector<nn::Index>;

Shape shape_of(const cnpy::NpyArray& a)
{
    Shape s;
    s.reserve(a.shape.size());
    for (size_t d : a.shape) s.push_back(static_cast<nn::Index>(d));
    return s;
}

template <typename Tensor>
float& elem(Tensor& t, const Shape& i)
{
    switch (i.size())
    {
        case 2:
            return t.at(i[0], i[1]);
        case 3:
            return t.at(i[0], i[1], i[2]);
        case 4:
            return t.at(i[0], i[1], i[2], i[3]);
        default:
            throw std::invalid_argument("parity test: unsupported tensor rank");
    }
}

template <typename Tensor>
float elem(const Tensor& t, const Shape& i)
{
    switch (i.size())
    {
        case 2:
            return t.at(i[0], i[1]);
        case 3:
            return t.at(i[0], i[1], i[2]);
        case 4:
            return t.at(i[0], i[1], i[2], i[3]);
        default:
            throw std::invalid_argument("parity test: unsupported tensor rank");
    }
}

// Advance a C-order multi-index; returns false after the last element.
bool next_index(Shape& idx, const Shape& shape)
{
    for (int d = static_cast<int>(idx.size()) - 1; d >= 0; --d)
    {
        if (++idx[static_cast<size_t>(d)] < shape[static_cast<size_t>(d)]) return true;
        idx[static_cast<size_t>(d)] = 0;
    }
    return false;
}

// Build a tensor of the fixture array's own shape, filled via structured indices.
template <typename Tensor>
Tensor make_from(const cnpy::NpyArray& a)
{
    const Shape s = shape_of(a);
    Tensor t = (s.size() == 2) ? Tensor(s[0], s[1]) : Tensor(s);
    const float* d = a.data<float>();
    size_t k = 0;
    Shape idx(s.size(), 0);
    do
    {
        elem(t, idx) = d[k++];
    } while (next_index(idx, s));
    return t;
}

// Build a 2-D (rows x cols) tensor from a flat C-order buffer of that shape.
template <typename Tensor>
Tensor make_2d_flat(const float* d, nn::Index rows, nn::Index cols)
{
    Tensor t(rows, cols);
    for (nn::Index i = 0; i < rows; ++i)
        for (nn::Index j = 0; j < cols; ++j)
            t.at(i, j) =
                d[static_cast<size_t>(i) * static_cast<size_t>(cols) + static_cast<size_t>(j)];
    return t;
}

// Overwrite an existing tensor's values from a fixture array of the same shape.
template <typename Tensor>
void fill_from(Tensor& dst, const cnpy::NpyArray& a)
{
    const Shape s = shape_of(a);
    ASSERT_EQ(static_cast<size_t>(dst.size()), a.num_vals);
    const float* d = a.data<float>();
    size_t k = 0;
    Shape idx(s.size(), 0);
    do
    {
        elem(dst, idx) = d[k++];
    } while (next_index(idx, s));
}

// Compare `got` to a C-order fixture array. Iterates got's OWN logical shape and
// reads the reference in lockstep C-order, so it is agnostic to backend storage
// order AND to a rank difference that flattens the same way (e.g. our LIF output
// is 2-D (T*B,F) while the reference is 3-D (T,B,F) — same C-order sequence).
template <typename Tensor>
void expect_close(const Tensor& got, const cnpy::NpyArray& ref, const std::string& what, float tol)
{
    ASSERT_EQ(static_cast<size_t>(got.size()), ref.num_vals) << what << ": size mismatch";
    const Shape s = got.get_shape();
    const float* d = ref.data<float>();
    size_t k = 0;
    Shape idx(s.size(), 0);
    do
    {
        EXPECT_NEAR(elem(got, idx), d[k], tol) << what << " at C-index " << k;
        ++k;
    } while (next_index(idx, s));
}

#ifdef NN_BACKEND_SYCL
using AllBackends = ::testing::Types<XT, CL, DV, SY>;
#else
using AllBackends = ::testing::Types<XT, CL, DV>;
#endif

template <typename B>
class PyTorchParityTyped : public ::testing::Test
{
   protected:
    using Backend = B;
    using Tensor = nn::TensorImpl<B>;

    void SetUp() override
    {
        skip_if_backend_unavailable<B>();
    }
    static float tol()
    {
        return parity_tol<B>();
    }
};

TYPED_TEST_SUITE(PyTorchParityTyped, AllBackends);

} // namespace

// ── Linear: forward + input/weight/bias gradients ─────────────────────────────
TYPED_TEST(PyTorchParityTyped, Linear)
{
    using B = typename TestFixture::Backend;
    using Tensor = typename TestFixture::Tensor;
    const float tol = TestFixture::tol();

    const int n = static_cast<int>(arr("linear_num").data<int64_t>()[0]);
    for (int i = 0; i < n; ++i)
    {
        const std::string p = "linear_" + std::to_string(i) + "_";
        const auto& W = arr(p + "weight");
        const int out_f = static_cast<int>(W.shape[0]);
        const int in_f = static_cast<int>(W.shape[1]);

        LinearImpl<B> lin(in_f, out_f);
        fill_from(lin.weight, W);
        fill_from(lin.bias, arr(p + "bias"));

        Tensor x = make_from<Tensor>(arr(p + "input"));
        Tensor y = lin.forward(x, true);
        expect_close(y, arr(p + "output"), p + "output", tol);

        Tensor go = make_from<Tensor>(arr(p + "grad_output"));
        Tensor gi = lin.backward(go);
        expect_close(gi, arr(p + "grad_input"), p + "grad_input", tol);
        expect_close(lin.weight.grad(), arr(p + "grad_weight"), p + "grad_weight", tol);
        expect_close(lin.bias.grad(), arr(p + "grad_bias"), p + "grad_bias", tol);
    }
}

// ── Elementwise activations: forward + backward ───────────────────────────────
namespace
{
template <typename Layer, typename Tensor>
void check_activation(const std::string& name, float tol)
{
    const std::string p = "act_" + name + "_";
    Layer layer;
    Tensor x = make_from<Tensor>(arr(p + "input"));
    Tensor y = layer.forward(x, true);
    expect_close(y, arr(p + "output"), p + "output", tol);

    Tensor go = make_from<Tensor>(arr(p + "grad_output"));
    Tensor gi = layer.backward(go);
    expect_close(gi, arr(p + "grad_input"), p + "grad_input", tol);
}
} // namespace

TYPED_TEST(PyTorchParityTyped, Tanh)
{
    using B = typename TestFixture::Backend;
    check_activation<TanhImpl<B>, typename TestFixture::Tensor>("tanh", TestFixture::tol());
}
