// ── MSELoss: scalar loss + gradient w.r.t. prediction ─────────────────────────
TYPED_TEST(PyTorchParityTyped, MSELoss)
{
    using B = typename TestFixture::Backend;
    using Tensor = typename TestFixture::Tensor;
    const float tol = TestFixture::tol();

    MSELossImpl<B> loss;
    loss.set_target(make_from<Tensor>(arr("mse_target")));
    Tensor pred = make_from<Tensor>(arr("mse_pred"));
    Tensor l = loss.forward(pred, true);
    EXPECT_NEAR(l.at(0, 0), arr("mse_loss").data<float>()[0], tol);

    Tensor gp = loss.backward(pred);
    expect_close(gp, arr("mse_grad_pred"), "mse_grad_pred", tol);
}

// ── LSTMLayer: forward (all hidden states) for a batched sequence ──────────────
//
// Our LSTM uses rational-approximation sigmoid/tanh (FastActivations.hpp) for
// speed, so it cannot bit-match PyTorch's exact activations. Two checks:
//   1. Tight vs. a numpy reference using the *same* rational approximation —
//      proves the recurrence, gate order (i,f,o,g), and weight orientation are
//      correct.
//   2. Loose vs. PyTorch's exact-activation output — documents the accuracy gap
//      the fast activations introduce (bounded well under the saturation error).
TYPED_TEST(PyTorchParityTyped, LSTMLayerForward)
{
    using B = typename TestFixture::Backend;
    using Tensor = typename TestFixture::Tensor;
    const float tol = TestFixture::tol();

    const int n = static_cast<int>(arr("lstm_num").data<int64_t>()[0]);
    for (int i = 0; i < n; ++i)
    {
        const std::string p = "lstm_" + std::to_string(i) + "_";
        const auto dims = arr(p + "dims").data<int64_t>();
        const int D = static_cast<int>(dims[2]);
        const int H = static_cast<int>(dims[3]);

        // ── (1) DEFAULT: exact activations must match torch.nn.LSTM exactly ──
        // exact_activations defaults to true, so our gates are the real sigmoid/tanh and
        // there is nothing left to approximate: this is a tight, element-wise comparison
        // against PyTorch itself. It used to be a loose 0.25 bound because the layer
        // unconditionally used FastActivations' softsign gates.
        {
            LSTMLayerImpl<B> layer(D, H);
            // Fixture weights are already in our gate order (i,f,o,g) with merged bias.
            fill_from(layer.W_, arr(p + "W"));
            fill_from(layer.U_, arr(p + "U"));
            fill_from(layer.b_, arr(p + "b"));
            ASSERT_TRUE(layer.exact_activations) << "exact activations must be the default";

            Tensor x = make_from<Tensor>(arr(p + "input"));
            layer.reset_state();
            Tensor y = layer.forward(x, false);
            expect_close(y, arr(p + "output"), p + "output (vs torch.nn.LSTM)", tol);
        }

        // ── (2) OPT-IN fast mode: matches the rational-approx recurrence, not torch ──
        // Kept so the speed/fidelity trade stays exercised and honest: when a profile sets
        // numerics.exact_activations=false the layer becomes a softsign-gated LSTM, which is
        // ~2x cheaper but provably NOT torch (|tanh - tanh_fast| reaches 0.306 on [-4,4]).
        {
            LSTMLayerImpl<B> layer(D, H);
            layer.exact_activations = false;
            fill_from(layer.W_, arr(p + "W"));
            fill_from(layer.U_, arr(p + "U"));
            fill_from(layer.b_, arr(p + "b"));

            Tensor x = make_from<Tensor>(arr(p + "input"));
            layer.reset_state();
            Tensor y = layer.forward(x, false);
            expect_close(y, arr(p + "output_approx"), p + "output_approx (fast mode)", tol);
        }
    }
}

// ── LifBPTT spiking neuron vs snnTorch Leaky ──────────────────────────────────
// Our recurrence v[t]=beta*v[t-1]+input[t], spike on v>V_th, subtract/zero reset
// matches snn.Leaky(beta, threshold, reset_mechanism). R=C=1, delta_t=-ln(beta)
// so beta = exp(-delta_t/(R*C)) reproduces snnTorch's beta.
TYPED_TEST(PyTorchParityTyped, LifBPTTvsSnnTorch)
{
    using B = typename TestFixture::Backend;
    using Tensor = typename TestFixture::Tensor;
    const float tol = TestFixture::tol();

    const int n = static_cast<int>(arr("lif_num").data<int64_t>()[0]);
    for (int i = 0; i < n; ++i)
    {
        const std::string p = "lif_" + std::to_string(i) + "_";
        const auto dims = arr(p + "dims").data<int64_t>();
        const int T = static_cast<int>(dims[0]);
        const int B_ = static_cast<int>(dims[1]);
        const int F = static_cast<int>(dims[2]);
        const float* prm = arr(p + "params").data<float>();
        const float delta_t = prm[0];
        const float R = prm[1];
        const float C = prm[2];
        const float vth = prm[3];
        const bool reset_zero = prm[4] > 0.5F;
        const bool readout = prm[5] > 0.5F;

        LifBPTTImpl<B> lif(T, delta_t, R, C, vth, reset_zero, 0.0F, readout);

        // Fixture input is (T,B,F) C-order == time-major (T*B, F) rows (t0 batch,
        // then t1 batch, …) — exactly what LifBPTT expects.
        const auto& in = arr(p + "input");
        Tensor x = make_2d_flat<Tensor>(
            in.data<float>(), static_cast<nn::Index>(T * B_), static_cast<nn::Index>(F));

        lif.reset_state();
        Tensor y = lif.forward(x, false);

        // readout → membrane (compare to snnTorch mem); spike mode → spike train.
        expect_close(y, arr(p + (readout ? "mem" : "spk")), p + (readout ? "mem" : "spk"), tol);
    }
}

// ── LifBPTT readout backward vs snnTorch autograd (exact BPTT temporal grad) ──
// Pure leaky integrator (readout mode, no spike/reset): dL/dinput through
// v[t]=beta*v[t-1]+input[t] for loss = sum(all membranes) must match snnTorch's
// autograd exactly (no surrogate/reset involved).
TYPED_TEST(PyTorchParityTyped, LifBPTTReadoutBackward)
{
    using B = typename TestFixture::Backend;
    using Tensor = typename TestFixture::Tensor;
    const float tol = TestFixture::tol();

    const int n = static_cast<int>(arr("lifbw_num").data<int64_t>()[0]);
    for (int i = 0; i < n; ++i)
    {
        const std::string p = "lifbw_" + std::to_string(i) + "_";
        const auto dims = arr(p + "dims").data<int64_t>();
        const int T = static_cast<int>(dims[0]);
        const int B_ = static_cast<int>(dims[1]);
        const int F = static_cast<int>(dims[2]);
        const float* prm = arr(p + "params").data<float>();

        LifBPTTImpl<B> lif(T,
            prm[0],
            prm[1],
            prm[2],
            /*V_th=*/1.0F,
            /*reset_zero=*/false,
            /*reset_potential=*/0.0F,
            /*readout_mode=*/true);

        // Arbitrary input; only the gradient path is checked (dL/dinput of a linear
        // integrator is input-independent). Fill via the structured accessor.
        Tensor x(static_cast<nn::Index>(T * B_), static_cast<nn::Index>(F));
        for (nn::Index r = 0; r < static_cast<nn::Index>(T * B_); ++r)
            for (nn::Index c = 0; c < static_cast<nn::Index>(F); ++c)
                x.at(r, c) = 0.1F * static_cast<float>(((r * F + c) % 7) - 3);

        lif.reset_state();
        (void) lif.forward(x, true);
        // loss = sum(all membranes) → dL/d(membrane)=1 everywhere.
        Tensor grad_out(static_cast<nn::Index>(T * B_), static_cast<nn::Index>(F));
        for (nn::Index r = 0; r < static_cast<nn::Index>(T * B_); ++r)
            for (nn::Index c = 0; c < static_cast<nn::Index>(F); ++c) grad_out.at(r, c) = 1.0F;

        Tensor grad_in = lif.backward(grad_out);
        expect_close(grad_in, arr(p + "grad_input"), p + "grad_input", tol);
    }
}

// ── Conv1d vs torch.nn.Conv1d (valid, stride 1) ───────────────────────────────
TYPED_TEST(PyTorchParityTyped, Conv1d)
{
    using B = typename TestFixture::Backend;
    using Tensor = typename TestFixture::Tensor;
    const float tol = TestFixture::tol();

    const int n = static_cast<int>(arr("conv1d_num").data<int64_t>()[0]);
    for (int i = 0; i < n; ++i)
    {
        const std::string p = "conv1d_" + std::to_string(i) + "_";
        const auto dims = arr(p + "dims").data<int64_t>();
        const int Cin = static_cast<int>(dims[1]);
        const int Cout = static_cast<int>(dims[2]);
        const int K = static_cast<int>(dims[4]);

        Conv1dImpl<B> conv(Cin, Cout, K, /*stride=*/1, /*padding=*/0, /*dilation=*/1);
        conv.set_weights(make_from<Tensor>(arr(p + "weight"))); // (Cin*K, Cout)
        conv.set_bias(make_from<Tensor>(arr(p + "bias")));      // (1, Cout)

        Tensor x = make_from<Tensor>(arr(p + "input")); // (N, Cin, L)
        Tensor y = conv.forward(x, false);              // (N, Cout, L-K+1)
        expect_close(y, arr(p + "output"), p + "output", tol);
    }
}

