TYPED_TEST(PyTorchParityTyped, MaxPool2d)
{
    using B = typename TestFixture::Backend;
    using Tensor = typename TestFixture::Tensor;
    const float tol = TestFixture::tol();

    const int n = static_cast<int>(arr("maxpool2d_num").data<int64_t>()[0]);
    for (int i = 0; i < n; ++i)
    {
        const std::string p = "maxpool2d_" + std::to_string(i) + "_";
        const auto pr = arr(p + "params").data<int64_t>();
        MaxPool2dImpl<B> pool(static_cast<int>(pr[0]), static_cast<int>(pr[1]));
        Tensor x = make_from<Tensor>(arr(p + "input")); // (N, C, H, W)
        Tensor y = pool.forward(x, false);
        expect_close(y, arr(p + "output"), p + "output", tol);
    }
}
